from pathlib import Path
import re,json
root=Path('/mnt/data/dottie_corpus_txt')

def clean(s):
    return re.sub(r'\s+',' ',s).strip()

def get_title(lines):
    # take non-empty lines before Abstract/arxiv/authors clutter; score title-ish lines
    c=[]
    for i,l in enumerate(lines[:120]):
        s=clean(l)
        if not s: continue
        if re.search(r'abstract',s,re.I): break
        if re.match(r'^(arXiv:|\d{1,2}\s*$|[A-Z][a-z]+\s+[A-Z])',s) and len(s)<80: pass
        if 10<len(s)<180 and not re.search(r'@|university|institute|department|correspond|http|www\.',s,re.I):
            c.append((i,s))
    # favor lines with colon/title capitalization and early
    if c:
        # often first or second candidate is title
        return c[0][1]
    return clean(lines[0]) if lines else ''

def extract_between(lines, start_patterns, stop_patterns=None, max_lines=180):
    start=None
    for i,l in enumerate(lines):
        s=clean(l)
        if any(re.fullmatch(p,s,re.I) for p in start_patterns):
            start=i+1; break
    if start is None:
        return ''
    end=min(len(lines),start+max_lines)
    if stop_patterns:
        for j in range(start+3,end):
            s=clean(lines[j])
            if any(re.fullmatch(p,s,re.I) for p in stop_patterns):
                end=j; break
    return clean(' '.join(lines[start:end]))

def find_section(lines, keyword_regex, max_lines=180):
    rx=re.compile(keyword_regex,re.I)
    for i,l in enumerate(lines):
        s=clean(l)
        if rx.fullmatch(s) or (rx.search(s) and len(s)<100):
            # until next obvious heading
            end=min(len(lines),i+max_lines)
            for j in range(i+5,end):
                t=clean(lines[j])
                if re.match(r'^\d+(?:\.\d+)*\s+[A-Z][A-Za-z0-9 ,:;\-()]{3,80}$',t) and not rx.search(t):
                    end=j;break
            return clean(' '.join(lines[i:end]))
    return ''

cards=[]
for p in sorted(root.glob('*.txt')):
    lines=p.read_text(errors='ignore').splitlines()
    title=get_title(lines)
    abstract=find_section(lines,r'(?:\d+(?:\.\d+)*)?\s*Abstract')
    conclusion=find_section(lines,r'(?:\d+(?:\.\d+)*)?\s*(?:Conclusion(?:s)?|Discussion and Conclusion|Concluding Remarks)')
    limitations=find_section(lines,r'(?:\d+(?:\.\d+)*)?\s*(?:Limitations?|Limitations and Future Work|Limitations and Broader Impacts|Ethical Considerations and Limitations)')
    cards.append({'file':p.name,'title':title,'abstract':abstract[:6000],'conclusion':conclusion[:6000],'limitations':limitations[:6000]})
Path('/mnt/data/dottie_cards.json').write_text(json.dumps(cards,indent=2))
# printable concise cards
with open('/mnt/data/dottie_cards.txt','w') as f:
    for c in cards:
        f.write('\n==== '+c['file']+' ====\nTITLE: '+c['title']+'\n')
        f.write('ABSTRACT: '+c['abstract'][:2500]+'\n')
        f.write('CONCLUSION: '+c['conclusion'][:2000]+'\n')
        f.write('LIMITATIONS: '+c['limitations'][:2000]+'\n')
print('wrote cards')
